# 方法一：縱向掃描（推薦）
class Solution:
    def longestCommonPrefix(self, strs: List[str]) -> str:
        if not strs:
            return ""

        first = strs[0]
        for i in range(len(first)):
            ch = first[i]
            for s in strs[1:]:
                # 走到某字串結尾，或字元不同 → 停止
                if i >= len(s) or s[i] != ch:
                    return first[:i]
        return first


# 方法二：橫向掃描
class Solution:
    def longestCommonPrefix(self, strs: List[str]) -> str:
        if not strs:
            return ""
        prefix = strs[0]
        for s in strs[1:]:
            while not s.startswith(prefix):
                prefix = prefix[:-1]     # 每次砍掉最後一個字元
                if not prefix:
                    return ""
        return prefix


# 方法三：排序取頭尾（最短的寫法）
class Solution:
    def longestCommonPrefix(self, strs: List[str]) -> str:
        if not strs:
            return ""
        strs.sort()
        first, last = strs[0], strs[-1]
        i = 0
        while i < len(first) and i < len(last) and first[i] == last[i]:
            i += 1
        return first[:i]

